mapper.delete:
delete
from
    todos
where
    id = #{id}
    and user_id = #{userId}

mapper.select:
select id, user_id, category_id, title, memo, due_date, due_time, priority, is_flagged, is_completed, completed_at, created_at, updated_at from todos
user_id = #{userId}
and due_date = #{condition.date}
and category_id = #{condition.categoryId}
